function m(n){return(n??60)===30?30:60}function s(n){const t=Math.floor(n/60),u=n%60,o=t<12?"AM":"PM";return`${t%12===0?12:t%12}:${String(u).padStart(2,"0")} ${o}`}function l(n,t){return`${s(n)} – ${s(t)}`}function f(n){return n.start_minute!=null?n.start_minute:n.start_hour>24?n.start_hour:n.start_hour*60}function c(n){return n.end_minute!=null?n.end_minute:n.end_hour>24?n.end_hour:n.end_hour*60}function M(n,t){const u=[...n].sort((o,r)=>o-r);return u.every((o,r)=>r===0||o===u[r-1]+t)}function h(n,t){return n.length===0?null:n[n.length-1]+t}function d(n,t){return n.length===0?[]:g(n[0],h(n,t),t)}function g(n,t,u){const o=Math.min(n,t),r=Math.max(n,t),i=[];for(let e=o;e<=r;e+=u)i.push(e);return i}function _(n,t,u){if(t===n)return{startMinute:n,endMinute:n+u,durationMinutes:u,slotStarts:[n]};const o=Math.min(n,t),r=Math.max(n,t),i=r-o,e=[];for(let a=o;a<r;a+=u)e.push(a);return{startMinute:o,endMinute:r,durationMinutes:i,slotStarts:e}}function S(n){return n/60}function b(n,t){return n.length>0&&n.every(u=>t.has(u))}function k(n,t,u){return Math.round(n*t*(u/60))}function $(n){return l(f(n),c(n))}function v(n){return s(f(n))}function p(n){if(!n)return null;if(n%60===0){const t=n/60;return t===1?"1 hour":`${t} hours`}return`${n} minutes`}export{_ as a,S as b,v as c,p as d,l as e,$ as f,s as g,b as h,M as i,k as j,m as k,g as l,h as s,d as v};
